void ScriptSession::removeItem(std::uint32_t handle) {if(!alive(handle,NativeKind::Item))return;auto state=items_.at(handle);if(alive(state->holder,NativeKind::Unit))for(auto& slot:units_.at(state->holder)->inventory)if(slot==handle)slot=0;auto holder=state->holder;items_.erase(handle);++fogRevision_;destroy(runtime_.handle("item",handle),NativeKind::Item);if(alive(holder,NativeKind::Unit))refreshEquipment(*units_.at(holder));}
